// # Section block_sibling_hedged: an escaping def inside a block copies the
// # sibling it calls, and the list that sibling holds, with the hedged wording.
// def block_sibling_hedged(out: list[Callable[[], int]], flag: bool) -> None:
//     xs = [1, 2]
//     xs.append(3)
//
//     def h() -> int:
//         return len(xs)
//     if flag:
//         def f() -> int:  # tpyc: warning(/Escaping closure 'f' copies nested function 'h', and with it its own copy of 'xs' \('h' may be used again after the closure definition, preventing a move\)\. Reorder/)
//             return h() + 1
//         out.append(f)
void block_sibling_hedged(std::vector<std::function<::tpy::BigInt()>>& out, bool flag) {
    std::vector<int32_t> xs = {1, 2};
    xs.push_back(3);
    auto h = [xs = std::move(xs)]() -> ::tpy::BigInt {
        return ::tpy::BigInt(::tpy::__len__(xs));
    };
    if (flag) {
        auto f = [h]() -> ::tpy::BigInt {
            return ((h()) + (::tpy::BigInt(1)));
        };
        out.push_back(f);
    }
}

// # Section dead_sibling: an earlier block-local `h` capturing `xs` is not the
// # `h` called after the escaping def, so `xs` still moves into `esc`.
// def dead_sibling(flag: bool) -> Callable[[], int]:
//     xs = [1, 2, 3]
//     xs.append(4)
//     if flag:
//         def h() -> int:
//             return len(xs)
//         print("dead_sibling inner", h())
//
//     def esc() -> int:  # tpyc: ok
//         return len(xs)
//
//     def h() -> int:
//         return 7
//     print("dead_sibling scope", h())
//     return esc
std::function<::tpy::BigInt()> dead_sibling(bool flag) {
    std::vector<int32_t> xs = {1, 2, 3};
    xs.push_back(4);
    if (flag) {
        auto h = [&xs]() -> ::tpy::BigInt {
            return ::tpy::BigInt(::tpy::__len__(xs));
        };
        std::cout << "dead_sibling inner" << " " << h() << "\n" << ::tpy::check_signals;
    }
    auto esc = [xs = std::move(xs)]() -> ::tpy::BigInt {
        return ::tpy::BigInt(::tpy::__len__(xs));
    };
    auto h = []() -> ::tpy::BigInt {
        return ::tpy::BigInt(7);
    };
    std::cout << "dead_sibling scope" << " " << h() << "\n" << ::tpy::check_signals;
    return esc;
}

// # Section per_case: one same-named def per `match` case.
// def per_case(k: int) -> int:
//     match k:
//         case 1:
//             def h() -> int:  # tpyc: ok
//                 return 1
//             return h()
//         case _:
//             def h() -> int:  # tpyc: ok
//                 return 2
//             return h()
::tpy::BigInt per_case(const ::tpy::BigInt& k) {
    auto& __match_subject_1 = k;
    if (__match_subject_1 == 1) {
        auto h = []() -> ::tpy::BigInt {
            return ::tpy::BigInt(1);
        };
        return h();
    } else {
        auto h = []() -> ::tpy::BigInt {
            return ::tpy::BigInt(2);
        };
        return h();
    }
    ::std::unreachable();
}

